Definition ls_foot (a : Z) : Prop :=
  0x10000 <= a < PML.IMG_RO_HI \/ 0xdba38 <= a < 0xdba41 \/ a = 0xdb840 \/ 0xdb5c0 <= a < 0xdb5c2 \/ 0xfd058 <= a < 0xfd058 + 544
